/// The plain-language phrases the narrative uses for one detector: what to
/// call it, what it looks for, and what it means when it flags something,
/// written for someone who isn't a forensics expert.
///
/// These are fixed templates. The narrative is assembled from them and the
/// findings' numbers and regions by `NarrativeGenerator`; nothing is
/// generated by a model or fetched from anywhere.
public struct DetectorWording: Sendable, Equatable {
    public let analyzerID: String

    /// What to call the check in prose, e.g. "the copy-paste check".
    public let name: String

    /// What the check looks for, as the end of "It ...": "looks for parts
    /// of the picture that were copied and pasted elsewhere in it".
    public let looksFor: String

    /// What a flag from this check means, as a full sentence.
    public let flagMeaning: String

    /// What else can trip the check, as a full sentence. Shown when the
    /// check is the main evidence.
    public let caveat: String

    public init(analyzerID: String, name: String, looksFor: String, flagMeaning: String, caveat: String) {
        self.analyzerID = analyzerID
        self.name = name
        self.looksFor = looksFor
        self.flagMeaning = flagMeaning
        self.caveat = caveat
    }

    /// Wording for every built-in detector.
    public static let builtIn: [DetectorWording] = [
        DetectorWording(
            analyzerID: "ela",
            name: "the re-save check (ELA)",
            looksFor: "checks whether every part of the image reacts the same way to being saved again as a JPEG",
            flagMeaning: "Some areas react differently to being re-saved than the rest of the picture, which happens when they were pasted in or retouched after the rest was saved.",
            caveat: "Sharp edges, text, and fine texture can react the same way in an untouched photo."
        ),
        DetectorWording(
            analyzerID: "metadata",
            name: "the file information check (EXIF)",
            looksFor: "reads the information the camera or editing program stored inside the file, such as the camera model, dates, and software",
            flagMeaning: "The information stored in the file shows signs of editing, such as an editing program's name or dates that don't line up.",
            caveat: "Editing programs are also used for harmless changes like cropping or resizing, and some apps rewrite this information on every save."
        ),
        DetectorWording(
            analyzerID: "clone",
            name: "the copy-paste check",
            looksFor: "looks for parts of the picture that were copied and pasted elsewhere in the same picture, even if rotated or resized",
            flagMeaning: "Part of the picture appears to have been copied and pasted into another spot in the same picture, a common way to hide or duplicate something.",
            caveat: "Genuinely repeating patterns, such as tiles, bricks, or a clear sky, can occasionally match too."
        ),
        DetectorWording(
            analyzerID: "doublecompression",
            name: "the double-save check",
            looksFor: "checks whether the photo was saved as a JPEG more than once",
            flagMeaning: "The photo appears to have been saved as a JPEG at least twice, which usually means it was opened, possibly changed, and saved again.",
            caveat: "Saving a photo again is not wrongdoing in itself: it only shows this isn't the camera's original file, not what changed."
        ),
        DetectorWording(
            analyzerID: "prnu",
            name: "the camera sensor-noise check (PRNU)",
            looksFor: "compares the faint, camera-specific noise pattern that a sensor leaves across every part of a photo",
            flagMeaning: "Some areas don't carry the same sensor noise as the rest of the picture, as if they came from another photo or were smoothed, resampled, or generated.",
            caveat: "Very dark, overexposed, or heavily textured areas can also look inconsistent."
        ),
        DetectorWording(
            analyzerID: "cfa",
            name: "the camera color-pattern check (CFA)",
            looksFor: "looks for the fine color pattern a camera's sensor leaves in every part of a photo when it builds a full-color image",
            flagMeaning: "Some areas are missing the camera's color pattern, or carry it shifted, as if they came from somewhere else or were rendered or resampled.",
            caveat: "Recompression, resizing, and phone camera processing weaken this pattern unevenly, so it's supporting evidence."
        ),
        DetectorWording(
            analyzerID: "jpegghost",
            name: "the JPEG quality-mismatch check (JPEG ghost)",
            looksFor: "checks whether every part of the image was saved at the same JPEG quality",
            flagMeaning: "Some areas appear to have been saved at a different JPEG quality than the rest, as if pasted in from another picture.",
            caveat: "Areas with very little detail give it little to measure."
        ),
        DetectorWording(
            analyzerID: "thumbnail",
            name: "the embedded-preview check",
            looksFor: "compares the small preview picture the camera stored inside the file with the picture itself",
            flagMeaning: "The small preview stored in the file no longer matches the picture, or has a different shape, so the picture was changed or cropped after it was taken.",
            caveat: "Some programs regenerate or keep old previews innocently, and rotating a photo without updating the preview also causes a mismatch."
        ),
        DetectorWording(
            analyzerID: "aigenerated",
            name: "the AI-generation traces check",
            looksFor: "looks for statistical traces common in AI-generated images: regular patterns left by image upscaling, and no camera sensor noise anywhere",
            flagMeaning: "The image shows statistical traces that are common in AI-generated images.",
            caveat: "It isn't a trained classifier: screenshots, graphics, and heavily processed photos can trip it, and it misses many generated images."
        ),
        DetectorWording(
            analyzerID: "noiselevel",
            name: "the noise-level check",
            looksFor: "compares how grainy each part of the picture is",
            flagMeaning: "Some areas are noticeably smoother or grainier than the rest of the picture, which can mean they came from a different source or were retouched.",
            caveat: "Shadows, blur, smooth surfaces, and fine texture change graininess in untouched photos too, so it's only a supporting hint."
        ),
    ]

    /// Wording for `analyzerID`, falling back to generic phrasing (using
    /// the identifier as the name) for analyzers without built-in wording.
    public static func wording(for analyzerID: String) -> DetectorWording {
        builtIn.first { $0.analyzerID == analyzerID }
            ?? DetectorWording(
                analyzerID: analyzerID,
                name: "the \(analyzerID) check",
                looksFor: "examines the image for signs of manipulation",
                flagMeaning: "It found something unusual.",
                caveat: "Its reliability isn't documented here, so its result is counted at a middling weight."
            )
    }
}
